def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)  # start checking from the next integer

    while True:
        if s == s[::-1]:
            return int(s)
        n = len(s)
        left_half = s[:n // 2]
        middle = s[n // 2] if n % 2 else ''
        if middle:
            # Construct palindrome by mirroring left_half + middle
            palindrome = left_half + middle + left_half[::-1]
        else:
            palindrome = left_half + left_half[::-1]

        if palindrome > s:
            s = palindrome
            return int(s)
        # increment the middle part (left + middle) as an integer and mirror again
        if middle:
            left_mid_num = int(left_half + middle) + 1
            left_mid_str = str(left_mid_num)
            if len(left_mid_str) > len(left_half + middle):
                # length increased, e.g. 999 + 1 = 1000, palindrome length increases
                s = '1' + ('0' * (n - 1)) + '1'
                continue
            s = left_mid_str + left_mid_str[:-1][::-1]
        else:
            left_num = int(left_half) + 1
            left_str = str(left_num)
            if len(left_str) > len(left_half):
                s = '1' + ('0' * (n - 1)) + '1'
                continue
            s = left_str + left_str[::-1]

