import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # cannot move if step length is zero
    if length >= d:
        return 1
    # If d > length, the minimal number of jumps is ceil(d / length),
    # except if d > length but d < 2*length and d != length, then 2 jumps are enough
    # because two jumps of length length can reach any point within a radius 2*length.
    # But if d > length, minimal jumps is ceil(d / length) except for the special case
    # when d < length * 2 and d != length, minimal jumps is 2.
    # This is a known geometric fact for such jumps.
    if d < 2 * length:
        return 2
    return math.ceil(d / length)

